def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    frames = []

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if (all(grid[r0][c] == color and grid[r1][c] == color
                for c in range(c0, c1 + 1)) and
            all(grid[r][c0] == color and grid[r][c1] == color
                for r in range(r0, r1 + 1))):
            frames.append((color, r0, r1, c0, c1))

    if not frames:
        return [row[:] for row in grid]

    groups = {}
    for frame in frames:
        _, r0, r1, c0, c1 = frame
        groups.setdefault((r1 - r0 + 1, c1 - c0 + 1), []).append(frame)
    chosen = max(groups.values(), key=len)

    donor = max(
        chosen,
        key=lambda f: sum(
            grid[r][c] == f[0]
            for r in range(f[1] + 1, f[2])
            for c in range(f[3] + 1, f[4])
        )
    )
    donor_color, dr0, dr1, dc0, dc1 = donor
    pattern = [
        [grid[r][c] == donor_color for c in range(dc0 + 1, dc1)]
        for r in range(dr0 + 1, dr1)
    ]

    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in chosen:
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = color
        for i, row in enumerate(pattern):
            for j, filled in enumerate(row):
                if filled:
                    out[r0 + 1 + i][c0 + 1 + j] = color
    return out
